#!/usr/bin/env python
"""
IRL Extension — Eval 00: data-availability audit. Run this BEFORE writing any section.

WHY THIS EXISTS
───────────────
Sections IV-H (retention / decertification over the six-week beta) and IV-I (usability
sessions) can only be written from real participant data. This script answers, with no
interpretation, the single question those sections depend on: *does that data exist?*

It also answers a question that has already caused two silent failures in this project:
*were the stored results generated by the code that is deployed now?* Result files survive
code edits. `eval_02`, `eval_03` and `eval_04` were collected on 2026-07-26; the response
templates and the entity resolver were rewritten on 2026-07-27/28. Numbers carried into a
table from a system that no longer exists are not a reporting problem, they are a
correctness problem, and nothing in the pipeline warns about it.

WHAT IT REPORTS
───────────────
  1. Participant inventory        real vs synthetic accounts, by activity
  2. Per-table row counts         how much of each telemetry stream exists
  3. Section IV-H feasibility     decertification events, retention intervals
  4. Section IV-F feasibility     prediction_log volume for Brier scoring
  5. Result-file staleness        every result file vs the mtime of the code it exercised
  6. traj_risk coverage           whether per-turn risk is being persisted yet

ACCOUNT CLASSIFICATION
──────────────────────
Synthetic accounts are identified by generator prefix (`irl6_`, `irleval_`, `e6-`, …),
by embedded hex (uuid fragments), and by the manual test conventions in this repo
(`STEST`, `CTEST`, `sec_*_verify`, `*_fresh_*`). Anything unmatched is reported as
POSSIBLY REAL and listed individually — the script never silently decides an account is a
study participant, because over-counting here would license writing a section that has no
data behind it.

USAGE
─────
    python IRL_extension_script/eval_00_data_audit.py
    python IRL_extension_script/eval_00_data_audit.py --list-accounts

OUTPUT
    IRL_extension_results/eval_00_data_audit.md
    IRL_extension_results/eval_00_staleness.csv
"""

from __future__ import annotations

import argparse
import os
import re
import sqlite3
from datetime import datetime

import pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, ".."))
OUT = os.path.join(ROOT, "IRL_extension_results")
os.makedirs(OUT, exist_ok=True)
DB_PATH = os.path.join(ROOT, "backend", "database", "ai_tutor.db")
REPORT = os.path.join(OUT, "eval_00_data_audit.md")
STALE_CSV = os.path.join(OUT, "eval_00_staleness.csv")

# Generator prefixes and manual test conventions used in this repo.
SYNTHETIC_PREFIX = re.compile(
    r"^(irl\d*_|irleval_|e6[-_]|eval|bench|smoke|test|stest|ctest|sec_|func_|"
    r"traj_|jail|redteam|probe|demo)", re.I)
HEXISH = re.compile(r"[0-9a-f]{6,}")
TEST_SUFFIX = re.compile(r"(_verify|_fresh|_x\d+|_v\d+)$", re.I)

# Which code paths each result family actually exercised. Staleness is only meaningful
# against the files whose behaviour the result depends on.

# ── behaviour-affecting change log ────────────────────────────────────────────
# File mtimes are too coarse to decide staleness: editing a docstring, or adding a
# telemetry field, touches the file without changing what the system answers. Every entry
# below is a change that alters OUTPUT, with the result families it invalidates. This is
# curated deliberately — an over-eager staleness check costs a re-run, but a missed one
# puts a number from a dead system into a table.
#
# Going forward, prefer `fingerprint()`: it hashes the source of the specific functions a
# result depends on, and the eval scripts record it at collection time. The log below
# covers results collected before that existed.
CODE_CHANGELOG = [
    # (when, what changed, invalidates prefixes)
    ("2026-07-27 22:11", "bkt_model._apply_decay: tz-aware timestamp normalisation. "
                         "Affects any decayed posterior read; does NOT affect _bkt_step "
                         "or EVIDENCE_CONFIG, so pure simulations are unaffected.",
     ["eval_06"]),
    ("2026-07-27 22:38", "cot_rag_agent._classify_mastery_level: scored entity resolution "
                         "(was first-fuzzy-match), conjunctive min rule (was pooled mean), "
                         "objective BKT (was self-blended P_eff). Changes the assigned "
                         "mastery level, hence the response.",
     ["eval_02", "eval_03", "eval_04", "eval_06"]),
    ("2026-07-28 00:25", "socratic.py: four structurally distinct level templates (was "
                         "three, with novice/developing sharing one), analogies restricted "
                         "to novice, level definitions restated as jobs. Changes response "
                         "content, length and code density directly.",
     ["eval_02", "eval_03", "eval_06"]),
    ("2026-07-30 00:00", "sentinel.py: goal-alignment latitude re-keyed from topics touched "
                         "to certified topics |K|, with a floor. Changes when a "
                         "security-sensitive query is blocked.",
     ["eval_04"]),
]

# Files whose edits do NOT change behaviour for these result families — used to suppress
# mtime false positives. Telemetry plumbing is observational: it records what happened, it
# does not alter it.
BEHAVIOUR_NEUTRAL_NOTE = (
    "Telemetry additions (traj_risk/traj_acc/traj_peak persistence, response_log columns) "
    "are observational and do not change any answer the system gives."
)

RESULT_DEPENDENCIES = {
    "eval_02_new_responses.json": [
        "backend/app/agents/socratic.py", "backend/app/agents/cot_rag_agent.py",
        "backend/app/core/fast_classifier.py",
    ],
    "eval_03_winrate_faithful.csv": [
        "backend/app/agents/socratic.py", "backend/app/agents/cot_rag_agent.py",
    ],
    "eval_03_winrate_debiased.csv": [
        "backend/app/agents/socratic.py", "backend/app/agents/cot_rag_agent.py",
    ],
    "eval_04_sessions.json": [
        "backend/app/agents/sentinel.py", "backend/app/agents/cot_rag_agent.py",
        "backend/app/core/fast_classifier.py",
    ],
    # eval_05 is a pure offline simulation: it imports _bkt_step and EVIDENCE_CONFIG and
    # touches no request path, so only bkt_model can stale it.
    "eval_05_archetypes.csv": ["backend/app/core/bkt_model.py"],
    "eval_05_sweep.csv": ["backend/app/core/bkt_model.py"],
    "eval_05_robustness.csv": ["backend/app/core/bkt_model.py"],
    "eval_06_responses.json": [
        "backend/app/agents/socratic.py", "backend/app/agents/cot_rag_agent.py",
        "backend/app/core/bkt_model.py",
    ],
    "eval_06_judge_tier.csv": [
        "backend/app/agents/socratic.py", "backend/app/agents/cot_rag_agent.py",
    ],
}


def classify(username: str) -> str:
    u = username or ""
    if SYNTHETIC_PREFIX.match(u) or HEXISH.search(u) or TEST_SUFFIX.search(u):
        return "synthetic"
    return "possibly_real"


def connect() -> sqlite3.Connection:
    con = sqlite3.connect(DB_PATH, timeout=30)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA busy_timeout=30000")
    return con


def q(con, sql, params=()) -> list:
    try:
        return [dict(r) for r in con.execute(sql, params)]
    except sqlite3.Error:
        return []


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--list-accounts", action="store_true",
                    help="list every possibly-real account individually")
    args = ap.parse_args()

    if not os.path.exists(DB_PATH):
        raise SystemExit(f"ERROR: DB not found at {DB_PATH}")

    con = connect()
    L: list[str] = []
    A = L.append
    A("# Eval 00 — data-availability audit\n")
    A(f"_Generated {datetime.now().isoformat(timespec='seconds')} · `{DB_PATH}`_\n")

    # ── 1. participants ───────────────────────────────────────────────────────
    turns = q(con, "SELECT username, ts_utc FROM turn_log")
    by_user: dict[str, list] = {}
    for r in turns:
        by_user.setdefault(r["username"] or "(null)", []).append(r["ts_utc"] or "")

    real = {u: ts for u, ts in by_user.items() if classify(u) == "possibly_real"}
    synth = {u: ts for u, ts in by_user.items() if classify(u) == "synthetic"}

    A("## 1. Participant inventory\n")
    A(f"- total turns: **{len(turns)}**")
    A(f"- synthetic / test accounts: **{len(synth)}** "
      f"({sum(len(v) for v in synth.values())} turns)")
    A(f"- possibly-real accounts: **{len(real)}** "
      f"({sum(len(v) for v in real.values())} turns)\n")

    if real:
        A("| account | turns | first | last |")
        A("|---|---:|---|---|")
        for u, ts in sorted(real.items(), key=lambda kv: -len(kv[1])):
            s = sorted(t for t in ts if t)
            A(f"| `{u}` | {len(ts)} | {s[0][:10] if s else '?'} | {s[-1][:10] if s else '?'} |")
        A("")
        A("These are *unmatched by the synthetic patterns*, not confirmed participants. "
          "Inspect the list before treating any of them as study data.\n")

    # ── 2. telemetry volume ───────────────────────────────────────────────────
    A("## 2. Telemetry stream volume\n")
    A("| table | rows | rows from possibly-real accounts |")
    A("|---|---:|---:|")
    tables = ["turn_log", "evidence_log", "prediction_log", "bkt_history",
              "response_log", "calibration_log", "jol_log", "mcn_log",
              "misconception_log", "path_event", "event_log", "session_log"]
    for t in tables:
        rows = q(con, f"SELECT username FROM {t}")
        if not rows:
            cnt = q(con, f"SELECT count(*) c FROM {t}")
            A(f"| `{t}` | {cnt[0]['c'] if cnt else '—'} | (no username column) |")
            continue
        n_real = sum(1 for r in rows if classify(r.get("username")) == "possibly_real")
        A(f"| `{t}` | {len(rows)} | {n_real} |")
    A("")

    # ── 3. Section IV-H feasibility ───────────────────────────────────────────
    A("## 3. Section IV-H feasibility — retention and decertification\n")
    A("§IV-H requires (a) certifications that later decayed below θ_dec and were "
      "decertified, and (b) retention intervals long enough for Eq. (17) to act. Both "
      "need real elapsed calendar time; neither can be produced by a replay harness.\n")

    cert_events = q(con, "SELECT username, concept, trigger, ts_utc FROM bkt_history "
                         "WHERE trigger IS NOT NULL")
    decert = [r for r in cert_events if "decert" in (r["trigger"] or "").lower()]
    certs = [r for r in cert_events if "cert" in (r["trigger"] or "").lower()
             and "decert" not in (r["trigger"] or "").lower()]
    ever = q(con, "SELECT count(*) c FROM user_knowledge WHERE ever_certified=1")
    now_cert = q(con, "SELECT count(*) c FROM user_knowledge WHERE is_certified=1")

    A(f"- certification events logged: **{len(certs)}**")
    A(f"- decertification events logged: **{len(decert)}**")
    A(f"- rows with `ever_certified=1`: **{ever[0]['c'] if ever else 0}**")
    A(f"- rows with `is_certified=1`: **{now_cert[0]['c'] if now_cert else 0}**")

    spans = []
    for u, ts in by_user.items():
        s = sorted(t for t in ts if t)
        if len(s) >= 2:
            try:
                d0 = datetime.fromisoformat(s[0].replace("Z", "+00:00"))
                d1 = datetime.fromisoformat(s[-1].replace("Z", "+00:00"))
                spans.append((u, (d1 - d0).days))
            except ValueError:
                pass
    longest = sorted(spans, key=lambda kv: -kv[1])[:5]
    A(f"- longest per-account activity span: "
      f"**{longest[0][1] if longest else 0} days** "
      f"(`{longest[0][0] if longest else '—'}`)")
    A("")
    feasible = bool(decert) and bool(longest) and longest[0][1] >= 14
    A(f"**Verdict: §IV-H is {'FEASIBLE' if feasible else 'NOT FEASIBLE'} from this database.**")
    if not feasible:
        A("No account shows both decertification events and a multi-week span. §IV-H "
          "cannot be written from local data. Either the beta ran on a deployed instance "
          "whose database has not been merged here, or it has not run. Resolve this "
          "before drafting §IV-H or §IV-A's participant counts.\n")

    # ── 4. Section IV-F feasibility ───────────────────────────────────────────
    A("## 4. Section IV-F feasibility — model calibration\n")
    pl = q(con, "SELECT username FROM prediction_log")
    pl_real = [r for r in pl if classify(r["username"]) == "possibly_real"]
    A(f"- `prediction_log` rows: **{len(pl)}** (possibly-real accounts: **{len(pl_real)}**)\n")
    A(f"**Verdict: {'sufficient' if len(pl_real) >= 200 else 'INSUFFICIENT'} for a "
      f"Brier-score claim.** A calibration curve on {len(pl_real)} paired "
      f"prediction/outcome records from test accounts is not reportable; label §IV-F "
      f"as requiring classroom deployment.\n")

    # ── 5. staleness ──────────────────────────────────────────────────────────
    A("## 5. Result-file staleness\n")
    A("A result is STALE if a change that alters system OUTPUT landed after it was "
      "collected. Judged against the curated change log, not file mtimes: mtime marks "
      "docstring edits and telemetry plumbing as breaking changes, which they are not. "
      f"{BEHAVIOUR_NEUTRAL_NOTE}\n")
    rows = []
    for fname, deps in RESULT_DEPENDENCIES.items():
        fpath = os.path.join(OUT, fname)
        if not os.path.exists(fpath):
            rows.append({"result": fname, "collected": "ABSENT", "status": "absent",
                         "invalidated_by": "", "mtime_flag": ""})
            continue
        f_mtime = os.path.getmtime(fpath)
        family = fname.split("_")[0] + "_" + fname.split("_")[1]

        breaking = [(w, what) for w, what, inval in CODE_CHANGELOG
                    if family in inval
                    and datetime.strptime(w, "%Y-%m-%d %H:%M").timestamp() > f_mtime]

        # Secondary signal only: a dependency touched with no matching changelog entry
        # means either a benign edit or an undocumented behaviour change.
        untracked = [d for d in deps
                     if os.path.exists(os.path.join(ROOT, d))
                     and os.path.getmtime(os.path.join(ROOT, d)) > f_mtime
                     and not breaking]

        rows.append({
            "result": fname,
            "collected": datetime.fromtimestamp(f_mtime).strftime("%Y-%m-%d %H:%M"),
            "status": "STALE" if breaking else "current",
            "invalidated_by": "; ".join(w for w, _ in breaking),
            "mtime_flag": "unlogged edit: " + ", ".join(os.path.basename(u) for u in untracked)
                          if untracked else "",
        })
    df = pd.DataFrame(rows)
    df.to_csv(STALE_CSV, index=False)
    A(df.to_markdown(index=False))
    A("")
    n_stale = int((df["status"] == "STALE").sum())
    if n_stale:
        A(f"**{n_stale} result file(s) are stale** and must be re-collected before their "
          f"numbers enter a table. Reasons, newest first:\n")
        for w, what, inval in reversed(CODE_CHANGELOG):
            A(f"- `{w}` — {what} → invalidates {', '.join(inval)}")
        A("")
    else:
        A("**All result files are current.**\n")
    if (df["mtime_flag"] != "").any():
        A("Rows carrying `unlogged edit` had a dependency touched with no changelog "
          "entry. Confirm the edit was behaviour-neutral, or add it to `CODE_CHANGELOG`.\n")

    # ── 6. traj_risk coverage ─────────────────────────────────────────────────
    A("## 6. Per-turn `traj_risk` coverage\n")
    cols = {r["name"] for r in q(con, "PRAGMA table_info(turn_log)")}
    have = "traj_risk" in cols
    if not have:
        A("`turn_log.traj_risk` does not exist — restart the server to apply the "
          "migration, then collect. Until then the trajectory layer's contribution can "
          "only be argued by elimination, and escalation recall cannot be computed.\n")
    else:
        tot = q(con, "SELECT count(*) c FROM turn_log")[0]["c"]
        nn = q(con, "SELECT count(*) c FROM turn_log WHERE traj_risk IS NOT NULL")[0]["c"]
        A(f"- turns with `traj_risk` recorded: **{nn}/{tot}**\n")
        if nn == 0:
            A("Column exists but nothing has been written yet — no turns have been served "
              "since the migration. Collect fresh data.\n")

    with open(REPORT, "w") as f:
        f.write("\n".join(L))
    con.close()

    print("\n".join(L))
    print(f"\n[audit] wrote {REPORT}")
    print(f"[audit] wrote {STALE_CSV}")

    if args.list_accounts and real:
        print("\nPossibly-real accounts:")
        for u in sorted(real):
            print(f"  {u}")


if __name__ == "__main__":
    main()
